package foodtests

// FIX #6 regression: PGStore.DetectMealMemory's case-sensitive comparison
// (distinctFoodNames, matchingDayCount, findAutoGeneratedSavedMeal in
// internal/food/learning.go) never matched a repeat logged with different
// capitalization. This exercises PGStore.DetectMealMemory directly (not the
// tests/food fakeStore mirror, which never reproduces SQL-level bugs) via a
// minimal db.Querier fake — see mealQuerier below.

import (
	"context"
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"lume/backend/internal/food"
)

type mealLogRow struct {
	userID, date, mealType, foodName string
}

type mealSavedMeal struct {
	id, userID, mealType string
	items                []string
	loggedCount          int
}

// mealQuerier is a minimal db.Querier stub covering only the Query/Exec
// shapes DetectMealMemory's "bump an existing auto_generated saved_meal"
// path issues (mirrors the fakeQuerier pattern in tests/cuisine/cuisine_test.go).
// createAutoGeneratedSavedMeal's Begin/Tx path is untouched by this fix and
// deliberately out of scope here, so QueryRow/Begin panic if hit.
type mealQuerier struct {
	logs       []mealLogRow
	savedMeals []*mealSavedMeal
}

func (q *mealQuerier) Query(_ context.Context, sql string, args ...any) (pgx.Rows, error) {
	switch {
	case strings.Contains(sql, "SELECT DISTINCT food_name FROM food_logs"):
		userID, date, mealType := args[0].(string), args[1].(string), args[2].(string)
		var rows [][]any
		seen := map[string]bool{}
		for _, l := range q.logs {
			if l.userID == userID && l.date == date && l.mealType == mealType && !seen[l.foodName] {
				seen[l.foodName] = true
				rows = append(rows, []any{l.foodName})
			}
		}
		return newMealRows(rows), nil
	case strings.Contains(sql, "SELECT date, food_name FROM food_logs"):
		userID, mealType := args[0].(string), args[1].(string)
		var rows [][]any
		for _, l := range q.logs {
			if l.userID == userID && l.mealType == mealType {
				d, err := time.Parse("2006-01-02", l.date)
				if err != nil {
					return nil, err
				}
				rows = append(rows, []any{d, l.foodName})
			}
		}
		return newMealRows(rows), nil
	case strings.Contains(sql, "SELECT id FROM saved_meals"):
		userID, mealType := args[0].(string), args[1].(string)
		var rows [][]any
		for _, sm := range q.savedMeals {
			if sm.userID == userID && sm.mealType == mealType {
				rows = append(rows, []any{sm.id})
			}
		}
		return newMealRows(rows), nil
	case strings.Contains(sql, "SELECT food_name FROM saved_meal_items"):
		id := args[0].(string)
		var rows [][]any
		for _, sm := range q.savedMeals {
			if sm.id == id {
				for _, name := range sm.items {
					rows = append(rows, []any{name})
				}
			}
		}
		return newMealRows(rows), nil
	}
	return nil, fmt.Errorf("mealQuerier: unhandled query: %s", sql)
}

func (q *mealQuerier) QueryRow(context.Context, string, ...any) pgx.Row {
	panic("mealQuerier: QueryRow not used by the bump-existing-saved-meal path")
}

func (q *mealQuerier) Begin(context.Context) (pgx.Tx, error) {
	panic("mealQuerier: Begin not used by the bump-existing-saved-meal path")
}

func (q *mealQuerier) Exec(_ context.Context, sql string, args ...any) (pgconn.CommandTag, error) {
	if strings.Contains(sql, "UPDATE saved_meals SET logged_count") {
		id := args[0].(string)
		for _, sm := range q.savedMeals {
			if sm.id == id {
				sm.loggedCount++
			}
		}
	}
	return pgconn.CommandTag{}, nil
}

// mealRows is a minimal pgx.Rows over an in-memory [][]any, supporting the
// *string / *time.Time scan destinations DetectMealMemory's queries use.
type mealRows struct {
	data [][]any
	idx  int
}

func newMealRows(data [][]any) *mealRows { return &mealRows{data: data, idx: -1} }

func (r *mealRows) Close()                                       {}
func (r *mealRows) Err() error                                   { return nil }
func (r *mealRows) CommandTag() pgconn.CommandTag                { return pgconn.CommandTag{} }
func (r *mealRows) FieldDescriptions() []pgconn.FieldDescription { return nil }
func (r *mealRows) Next() bool {
	r.idx++
	return r.idx < len(r.data)
}
func (r *mealRows) Scan(dest ...any) error {
	row := r.data[r.idx]
	for i, d := range dest {
		switch dv := d.(type) {
		case *string:
			*dv = row[i].(string)
		case *time.Time:
			*dv = row[i].(time.Time)
		default:
			return fmt.Errorf("mealRows.Scan: unsupported dest %T", d)
		}
	}
	return nil
}
func (r *mealRows) Values() ([]any, error) { return r.data[r.idx], nil }
func (r *mealRows) RawValues() [][]byte    { return nil }
func (r *mealRows) Conn() *pgx.Conn        { return nil }

func TestDetectMealMemoryNormalizesCaseWhenMatchingExistingSavedMeal(t *testing.T) {
	q := &mealQuerier{}
	userID, mealType := "user_1", "lunch"
	for _, d := range []string{"2026-06-15", "2026-06-25", "2026-07-05"} {
		q.logs = append(q.logs,
			mealLogRow{userID, d, mealType, "Rice"},
			mealLogRow{userID, d, mealType, "Dal"},
		)
	}
	sm := &mealSavedMeal{id: "meal_1", userID: userID, mealType: mealType, items: []string{"Rice", "Dal"}, loggedCount: 1}
	q.savedMeals = append(q.savedMeals, sm)

	// 4th day: same combo, different case — previously never matched.
	today := "2026-07-11"
	q.logs = append(q.logs,
		mealLogRow{userID, today, mealType, "rice"},
		mealLogRow{userID, today, mealType, "dal"},
	)

	store := food.NewPGStore(q)
	if err := store.DetectMealMemory(context.Background(), userID, today, mealType); err != nil {
		t.Fatalf("DetectMealMemory: %v", err)
	}
	if sm.loggedCount != 2 {
		t.Errorf("logged_count = %d, want 2 (differently-cased repeat should still match the existing auto_generated saved_meal)", sm.loggedCount)
	}
}
